<script lang="ts">
 import { onMount } from 'svelte';
 import { defaultAircraft, presets, clone, planform, validateAircraft, type AircraftDefinition, type Controls, type FlightMode, type Wing } from './model';
 import { FlightSimulation, derive } from './physics';
 import { SceneView } from './scene';
 import { listAircraft, saveAircraft, deleteAircraft, renameAircraft, duplicateAircraft, exportAircraft, importAircraft, readBest, writeBest, History, type SavedAircraft } from './storage';
 import WingEditor from './WingEditor.svelte'; import Parameter from './Parameter.svelte';
 type Tab='机身'|'主翼'|'水平尾翼'|'垂直尾翼'|'组装';
 let host:HTMLDivElement;let scene:SceneView;let simulation:FlightSimulation|null=null;let history=new History(clone(defaultAircraft));let historyVersion=$state(0);
 let aircraft=$state.raw<AircraftDefinition>(clone(defaultAircraft));let tab=$state<Tab>('主翼');let screen=$state<'menu'|'design'|'flight'|'result'>('menu');let mode=$state<FlightMode>('standard');let quality=$state<'Auto'|'High'|'Medium'|'Low'>('Auto');
 let saved=$state.raw<SavedAircraft[]>([]),selectedId=$state(''),message=$state(''),showLibrary=$state(false),debug=$state(false),paused=$state(false);let best=$state(0);let result=$state<any>(null),hud=$state<any>({speed:10,altitude:10,distance:0,alpha:0,pitch:0,roll:0,sink:0,glide:0,time:0});let perf=$state<any>({});
 let stats=$derived(derive(aircraft));let main=$derived(planform(aircraft.mainWing));let wingKey=$derived<'mainWing'|'horizontalTail'|'verticalTail'>(tab==='水平尾翼'?'horizontalTail':tab==='垂直尾翼'?'verticalTail':'mainWing');
 let recording:ReturnType<FlightSimulation['getRecording']>|null=null;let recordedLength=$state(0);let isReplay=$state(false);let lastDefinition=clone(defaultAircraft),lastMode:FlightMode='standard';
 let weight=$state(0),rudder=$state(0),elevator=$state(0),aileron=$state(0);const keys=new Set<string>();const controls:Controls={weight:0,rudder:0,elevator:0,aileron:0};
 const hints:Record<Tab,string>={'机身':'驾驶舱的位置改变重心。过度靠后可能让飞机俯仰失稳。','主翼':'拖动四个控制点。增加面积降低翼载荷，但增加重量与阻力。','水平尾翼':'增大尾翼或后移安装位置，通常提高俯仰稳定性。','垂直尾翼':'垂直尾翼提供偏航恢复力矩。太小容易偏离航向。','组装':'位置单位为米，正值朝机头。安装角同时改变外观与有效迎角。'};
 function notify(s:string){message=s;}
 function commit(){try{validateAircraft(aircraft);history.push(clone(aircraft));historyVersion++;}catch(e){notify((e as Error).message);}}
 function change(mutator:(d:AircraftDefinition)=>void){const d=clone(aircraft);mutator(d);try{validateAircraft(d);aircraft=d;scene?.updateAircraft(d);}catch(e){notify((e as Error).message);}}
 function replace(d:AircraftDefinition){aircraft=clone(d);scene?.updateAircraft(aircraft);commit();}
 function undo(){const d=history.undo();if(d){aircraft=clone(d);selectedId='';scene?.updateAircraft(aircraft);historyVersion++;}}
 function redo(){const d=history.redo();if(d){aircraft=clone(d);selectedId='';scene?.updateAircraft(aircraft);historyVersion++;}}
 function library(){try{saved=listAircraft();showLibrary=!showLibrary;}catch(e){notify((e as Error).message);}}
 function save(){try{const item=saveAircraft(aircraft,selectedId||undefined);selectedId=item.id;saved=listAircraft();notify('飞机已保存在此浏览器');}catch(e){notify((e as Error).message);}}
 function load(id:string){const item=saved.find(s=>s.id===id);if(item){replace(item.definition);selectedId=id;notify('已加载 '+item.name);}}
 function renameSaved(id:string,name:string){try{const item=renameAircraft(id,name);saved=listAircraft();if(selectedId===id){change(d=>d.name=item.name);commit();}}catch(e){notify((e as Error).message);}}
 function fileExport(){const url=URL.createObjectURL(new Blob([exportAircraft(aircraft)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=aircraft.name+'.json';a.click();URL.revokeObjectURL(url);}
 async function fileImport(e:Event){const input=e.target as HTMLInputElement;try{const f=input.files?.[0];if(f){if(f.size>100000)throw Error('文件超过 100 KB');replace(importAircraft(await f.text()));selectedId='';notify('导入成功');}}catch(e){notify('导入失败：'+(e as Error).message);}input.value='';}
 function start(replay=false){try{lastDefinition=replay?lastDefinition:clone(aircraft);lastMode=replay?lastMode:mode;simulation=new FlightSimulation(lastDefinition,lastMode);if(replay&&recording)simulation.loadReplay(recording);isReplay=replay;screen='flight';result=null;paused=false;keys.clear();weight=rudder=elevator=aileron=0;scene.setFlight(simulation);scene.setDebug(debug||mode==='experimental');scene.cameraView('追尾');}catch(e){notify((e as Error).message);}}
 function finish(){if(!simulation)return;result=simulation.result;recordedLength=simulation.recordingLength;screen='result';if(!isReplay){recording=simulation.getRecording();try{best=writeBest(mode,result.distance);}catch(e){notify((e as Error).message);}}}
 function design(){screen='design';simulation=null;scene?.setFlight(null);scene?.updateAircraft(aircraft);scene?.cameraView('轨道');keys.clear();weight=rudder=elevator=aileron=0;}
 function keyboard(e:KeyboardEvent,down:boolean){if((e.target as HTMLElement).matches('input,select,textarea'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(down)keys.add(e.key.toLowerCase());else keys.delete(e.key.toLowerCase());if(down&&e.key===' '&&screen==='flight')paused=!paused;if(down&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}}
 onMount(()=>{scene=new SceneView(host);scene.updateAircraft(aircraft);let previous=performance.now(),accumulator=0,lastUI=0;let request=0;
 const tick=(now:number)=>{let elapsed=Math.min((now-previous)/1000,0.1);previous=now;if(!document.hidden){if(screen==='flight'&&simulation&&!paused){accumulator+=elapsed;let steps=0;while(accumulator>=1/60&&steps<5){controls.weight=Math.max(-1,Math.min(1,weight+(keys.has('arrowup')||keys.has('w')?1:0)-(keys.has('arrowdown')||keys.has('s')?1:0)));controls.rudder=Math.max(-1,Math.min(1,rudder+(keys.has('arrowright')||keys.has('d')?1:0)-(keys.has('arrowleft')||keys.has('a')?1:0)));controls.elevator=elevator;controls.aileron=aileron;simulation.step(controls,1/60);accumulator-=1/60;steps++;if(simulation.ended){finish();accumulator=0;break;}}if(steps===5)accumulator=0;}else accumulator=0;scene.render(elapsed);if(now-lastUI>150){if(simulation)hud={...simulation.telemetry,alpha:simulation.telemetry.alpha*180/Math.PI,pitch:simulation.telemetry.pitch*180/Math.PI,roll:simulation.telemetry.roll*180/Math.PI,time:simulation.time};perf={...scene.metrics,physicsMs:simulation?.telemetry.physicsMs??0};lastUI=now;}}request=requestAnimationFrame(tick);};request=requestAnimationFrame(tick);
 const down=(e:KeyboardEvent)=>keyboard(e,true),up=(e:KeyboardEvent)=>keyboard(e,false),blur=()=>{keys.clear();weight=rudder=elevator=aileron=0;};window.addEventListener('keydown',down);window.addEventListener('keyup',up);window.addEventListener('blur',blur);document.addEventListener('visibilitychange',blur);
 try{saved=listAircraft();best=readBest(mode);}catch(e){notify((e as Error).message);}
 // Read-only diagnostics for automated measurement; interaction tests still use visible controls.
 Object.assign(window,{glider:{get aircraft(){return clone(aircraft)},get state(){return screen},get metrics(){return {...scene.metrics,physicsMs:simulation?.telemetry.physicsMs??0}},get telemetry(){return simulation?.telemetry},get result(){return result}}});
 return()=>{cancelAnimationFrame(request);scene.dispose();window.removeEventListener('keydown',down);window.removeEventListener('keyup',up);window.removeEventListener('blur',blur);document.removeEventListener('visibilitychange',blur);};});
 function touch(e:PointerEvent,key:'weight'|'rudder',value:number){e.currentTarget instanceof HTMLElement&&e.currentTarget.setPointerCapture(e.pointerId);if(key==='weight')weight=value;else rudder=value;}
</script>
<svelte:head><title>湖风滑翔 · 设计与飞行</title></svelte:head>
<div class="app" class:flying={screen==='flight'}>
 <div class="scene" bind:this={host} aria-label="三维滑空机与湖面场景"></div>
 <header class="topbar"><button class="brand" onclick={()=>screen==='flight'?paused=!paused:screen='menu'} aria-label="返回主菜单"><svg viewBox="0 0 36 28" width="34" height="28" fill="none" aria-hidden="true"><path d="M2 10 33 3 23 13 19 25 14 14 2 10Z" stroke="currentColor" stroke-width="1.7"/><path d="m14 14 19-11" stroke="currentColor"/></svg><span>湖风滑翔<small>LAKEWIND GLIDER</small></span></button><nav aria-label="游戏流程"><button class:active={screen==='design'&&tab!=='组装'} onclick={design}>设计</button><button class:active={screen==='design'&&tab==='组装'} onclick={()=>{design();tab='组装';}}>组装</button><button class:active={screen==='flight'||screen==='result'} onclick={()=>start()}>试飞</button></nav><div class="top-actions"><label class="quality-label">画质 <select aria-label="画质" bind:value={quality} onchange={()=>scene?.setQuality(quality)}><option>Auto</option><option>High</option><option>Medium</option><option>Low</option></select></label><button class="text-button" onclick={()=>{debug=!debug;scene?.setDebug(debug);}} aria-pressed={debug}>性能</button></div></header>
 {#if screen==='menu'}
 <main class="welcome"><h1>让设计，<br/>乘风而起。</h1><p>一架轻盈的飞机，一片开阔的湖。<br/>从机翼的每一条线开始，寻找更远的可能。</p><button class="primary large" onclick={design}>开始设计 <span>↗</span></button><button class="secondary" onclick={()=>start()}>先试飞默认飞机</button><div class="welcome-note">10 m 起飞平台 · 无风公平比赛 · 本地保存</div></main>
 <aside class="menu-caption"><span>湖风 01 / 均衡型</span><p>14.0 m 翼展 <b>·</b> 参数化轻型滑空机</p></aside>
 {:else if screen==='design'}
 <aside class="editor"><div class="editor-heading"><div><h1>飞机工坊</h1><p>每一次调整，都是下一次远航。</p></div><button class="text-button" onclick={library}>机库</button></div><div class="name-row"><input aria-label="飞机名称" value={aircraft.name} maxlength="60" onchange={e=>{change(d=>d.name=e.currentTarget.value);commit();}}/><button onclick={save}>保存</button></div><div class="history"><button disabled={!historyVersion||!history.canUndo} onclick={undo}>撤销</button><button disabled={!historyVersion||!history.canRedo} onclick={redo}>重做</button><button onclick={()=>{replace(defaultAircraft);selectedId='';}}>重置设计</button></div>
 <div class="tabs" role="tablist" aria-label="部件编辑">{#each ['机身','主翼','水平尾翼','垂直尾翼','组装'] as t}<button role="tab" aria-selected={tab===t} class:active={tab===t} onclick={()=>tab=t as Tab}>{t}</button>{/each}</div>
 <div class="editor-content"><h2>{tab==='组装'?'位置与配平':tab+'设计'}</h2><p class="help">{hints[tab]}</p>
 {#if tab==='机身'}
 <Parameter label="机身长度" value={aircraft.fuselage.length} min={3} max={12} unit="m" onchange={n=>change(d=>d.fuselage.length=n)} oncommit={commit} hint="长度增加结构重量。尾翼位置可在组装中独立调整。"/>
 <Parameter label="驾驶舱位置" value={aircraft.cockpit.position} min={-3} max={4} unit="m" onchange={n=>change(d=>d.cockpit.position=n)} oncommit={commit} hint="正值向机头移动。驾驶员是整机主要质量来源。"/>
 <Parameter label="驾驶员质量" value={aircraft.pilot.mass} min={40} max={100} step={1} unit="kg" onchange={n=>change(d=>d.pilot.mass=n)} oncommit={commit}/>
 <Parameter label="重心操纵行程" value={aircraft.controls.travel} min={0.1} max={0.8} step={0.05} unit="m" onchange={n=>change(d=>d.controls.travel=n)} oncommit={commit}/>
 {:else if tab==='组装'}
 <Parameter label="主翼纵向位置" value={aircraft.assembly.mainWing} min={-6} max={5} unit="m" onchange={n=>change(d=>d.assembly.mainWing=n)} oncommit={commit}/>
 <Parameter label="主翼安装高度" value={aircraft.assembly.mainWingHeight} min={0} max={2} unit="m" onchange={n=>change(d=>d.assembly.mainWingHeight=n)} oncommit={commit}/>
 <Parameter label="主翼安装角" value={aircraft.assembly.mainIncidence} min={-10} max={18} unit="°" onchange={n=>change(d=>d.assembly.mainIncidence=n)} oncommit={commit} hint="提高安装角会增加有效迎角；过大可能失速。"/>
 <Parameter label="水平尾翼位置" value={aircraft.assembly.horizontalTail} min={-6} max={5} unit="m" onchange={n=>change(d=>d.assembly.horizontalTail=n)} oncommit={commit}/>
 <Parameter label="水平尾翼安装角" value={aircraft.assembly.tailIncidence} min={-12} max={12} unit="°" onchange={n=>change(d=>d.assembly.tailIncidence=n)} oncommit={commit}/>
 <Parameter label="垂直尾翼位置" value={aircraft.assembly.verticalTail} min={-6} max={5} unit="m" onchange={n=>change(d=>d.assembly.verticalTail=n)} oncommit={commit}/>
 <Parameter label="驾驶舱位置" value={aircraft.cockpit.position} min={-3} max={4} unit="m" onchange={n=>change(d=>d.cockpit.position=n)} oncommit={commit}/>
 <div class="stability"><b>重心 X {stats.cg.x.toFixed(2)} m</b><span>主翼参考点 {(aircraft.assembly.mainWing-main.chord*0.25).toFixed(2)} m</span><span>估算静稳定裕度 {(stats.staticMargin*100).toFixed(1)} %</span><p>{stats.staticMargin<0?'重心偏后：可能俯仰失稳。请试飞验证。':stats.staticMargin>0.35?'重心偏前：可能难以抬头。':'具备正稳定裕度；安装角仍会影响配平。'}</p></div>
 {:else}
 {#key wingKey}<WingEditor value={aircraft[wingKey]} vertical={tab==='垂直尾翼'} onchange={(w:Wing)=>change(d=>d[wingKey]=w)} oncommit={commit}/>{/key}
 {#if tab==='主翼'}<Parameter label="主翼上反角" value={aircraft.mainWing.dihedral} min={0} max={25} unit="°" onchange={n=>change(d=>d.mainWing.dihedral=n)} oncommit={commit} hint="增加侧滑时的滚转恢复效应，不会强制飞机自动水平。"/>{/if}
 {/if}
 <div class="preset"><label for="preset">试试不同设计</label><select id="preset" aria-label="预设飞机" onchange={e=>{const n=+e.currentTarget.value;if(n>=0){replace(presets[n]);selectedId='';}}}><option value="-1">选择预设飞机</option>{#each presets as p,i}<option value={i}>{p.name}</option>{/each}</select></div>
 </div><div class="editor-footer"><label>飞行模式<select aria-label="飞行模式" bind:value={mode} onchange={()=>{try{best=readBest(mode);}catch{best=0;}}}><option value="standard">标准 · 公平竞赛</option><option value="assisted">辅助 · 额外阻尼</option><option value="experimental">实验 · 完整操纵</option></select></label><button class="primary" onclick={()=>start()}>前往平台试飞 <span>↗</span></button></div></aside>
 <div class="viewport-tools" aria-label="设计相机">{#each ['轨道','俯视','侧视','正视','后视'] as c}<button onclick={()=>scene.cameraView(c)}>{c}</button>{/each}</div><div class="scene-hint">拖动旋转 · 双指缩放 · 右键平移 <span><i></i> 重心 CG</span></div>
 <section class="design-metrics" aria-label="飞机性能估算"><div><small>机翼面积</small><strong>{main.area.toFixed(2)} <em>m²</em></strong></div><div><small>翼展 / 展弦比</small><strong>{main.span.toFixed(1)} <em>m / {main.aspect.toFixed(1)}</em></strong></div><div><small>全备质量</small><strong>{stats.mass.toFixed(1)} <em>kg</em></strong></div><div><small>翼载荷</small><strong>{stats.wingLoading.toFixed(2)} <em>kg/m²</em></strong></div><div><small>估算最佳滑翔比</small><strong>{stats.glideRatio.toFixed(1)} <em>: 1</em></strong></div></section>
 {:else if screen==='flight'}
 <section class="flight-hud" aria-label="飞行数据"><div><small>滑翔距离</small><strong>{hud.distance.toFixed(1)}<em>m</em></strong></div><div><small>空速</small><strong>{hud.speed.toFixed(1)}<em>m/s</em></strong></div><div><small>高度</small><strong>{hud.altitude.toFixed(1)}<em>m</em></strong></div><div><small>时间</small><strong>{hud.time.toFixed(1)}<em>s</em></strong></div></section>
 <div class="flight-status">{isReplay?'输入重放':mode==='assisted'?'辅助模式 · 独立成绩':mode==='experimental'?'实验模式':'标准模式 · 无风'}{#if hud.stall}<b>迎角过大 · 失速</b>{/if}</div>
 <div class="flight-tools"><button onclick={()=>paused=!paused}>{paused?'继续飞行':'暂停'}</button><select aria-label="飞行相机" onchange={e=>scene.cameraView(e.currentTarget.value)}>{#each ['追尾','侧面','驾驶员','自由'] as c}<option>{c}</option>{/each}</select><button onclick={design}>返回设计</button></div>
 {#if paused}<div class="pause-banner">飞行已暂停 <button onclick={()=>paused=false}>继续</button></div>{/if}
 <div class="flight-controls"><div><span>重心前后 · W / S</span><button aria-label="重心前移" onpointerdown={e=>touch(e,'weight',1)} onpointerup={()=>weight=0} onpointercancel={()=>weight=0}>前移</button><button aria-label="重心后移" onpointerdown={e=>touch(e,'weight',-1)} onpointerup={()=>weight=0} onpointercancel={()=>weight=0}>后移</button><progress max="2" value={weight+1} aria-label="重心操纵输入"></progress></div><div><span>方向舵 · A / D</span><button aria-label="向左转向" onpointerdown={e=>touch(e,'rudder',-1)} onpointerup={()=>rudder=0} onpointercancel={()=>rudder=0}>左转</button><button aria-label="向右转向" onpointerdown={e=>touch(e,'rudder',1)} onpointerup={()=>rudder=0} onpointercancel={()=>rudder=0}>右转</button><progress max="2" value={rudder+1} aria-label="方向操纵输入"></progress></div></div>
 <details class="advanced-hud"><summary>高级飞行数据</summary><p>迎角 {hud.alpha.toFixed(1)}° · 俯仰 {hud.pitch.toFixed(1)}° · 滚转 {hud.roll.toFixed(1)}°</p><p>下沉率 {hud.sink.toFixed(2)} m/s · 滑翔比 {Number.isFinite(hud.glide)?hud.glide.toFixed(1):'—'}</p>{#if mode==='experimental'}<label>升降舵<input aria-label="升降舵" type="range" min="-1" max="1" step="0.05" bind:value={elevator}/></label><label>副翼<input aria-label="副翼" type="range" min="-1" max="1" step="0.05" bind:value={aileron}/></label>{/if}</details>
 {:else if screen==='result'&&result}
 <section class="results"><div class="result-heading"><h1>每一米，都来自你的设计。</h1><span>{isReplay?'飞行重放':mode==='assisted'?'辅助组成绩':mode==='experimental'?'实验组成绩':'标准组成绩'}</span></div><div class="score">{result.distance.toFixed(2)}<small>m</small></div><p class="best">个人最佳 {best.toFixed(2)} m · {result.landing==='water'?'接触湖面':result.landing==='platform'?'撞击平台':result.landing==='terrain'?'撞击地形':'达到飞行边界'}</p><dl><div><dt>飞行时间</dt><dd>{result.time.toFixed(2)} s</dd></div><div><dt>平均速度</dt><dd>{result.averageSpeed.toFixed(2)} m/s</dd></div><div><dt>最高速度</dt><dd>{result.maxSpeed.toFixed(2)} m/s</dd></div><div><dt>最低速度</dt><dd>{result.minSpeed.toFixed(2)} m/s</dd></div><div><dt>最大高度</dt><dd>{result.maxHeight.toFixed(2)} m</dd></div><div><dt>输入记录</dt><dd>{recordedLength} 步 · 60 Hz</dd></div></dl><div class="flight-analysis"><h2>这次飞行的线索</h2>{#each result.hints as hint}<p>{hint}</p>{/each}</div><div class="result-actions"><button class="primary" onclick={design}>返回设计改进</button><button onclick={()=>start()}>再试一次</button><button onclick={()=>start(true)}>重放飞行</button></div></section>
 {/if}
 {#if showLibrary&&screen==='design'}<section class="library" aria-label="本地机库"><div class="library-title"><h2>本地机库</h2><button onclick={()=>showLibrary=false}>关闭</button></div><p>飞机保存在当前浏览器。导出 JSON 可备份或分享。</p><div class="library-actions"><button onclick={save}>保存当前飞机</button><button onclick={fileExport}>导出 JSON</button><label class="button">导入 JSON<input aria-label="导入飞机文件" type="file" accept=".json,application/json" onchange={fileImport}/></label></div>{#if !saved.length}<p class="empty">机库还没有飞机。先保存你的第一个设计。</p>{/if}{#each saved as s}<article class="saved-plane"><input aria-label={'重命名'+s.name} value={s.name} maxlength="60" onchange={e=>renameSaved(s.id,e.currentTarget.value)}/><small>{new Date(s.updatedAt).toLocaleString()}</small><div><button onclick={()=>load(s.id)}>加载</button><button onclick={()=>{try{duplicateAircraft(s.id);saved=listAircraft();}catch(e){notify((e as Error).message);}}}>复制</button><button onclick={()=>{if(confirm('删除“'+s.name+'”？此操作不可撤销。')){try{deleteAircraft(s.id);saved=listAircraft();if(selectedId===s.id)selectedId='';}catch(e){notify((e as Error).message);}}}}>删除</button></div></article>{/each}</section>{/if}
 {#if debug}<aside class="performance" aria-label="开发性能面板"><h2>性能实测 <button onclick={()=>debug=false}>关闭</button></h2><p>{perf.quality} · {Number(perf.fps||0).toFixed(1)} FPS</p><p>平均 {Number(perf.mean||0).toFixed(2)} ms · P95 {Number(perf.p95||0).toFixed(2)} ms · P99 {Number(perf.p99||0).toFixed(2)} ms</p><p>物理 {Number(perf.physicsMs||0).toFixed(3)} ms · 渲染提交 {Number(perf.renderMs||0).toFixed(2)} ms</p><p>几何 {Number(perf.geometryMs||0).toFixed(2)} ms · {perf.drawCalls||0} draw calls · {perf.triangles||0} triangles</p><p>几何与纹理估算 {typeof perf.memory==='number'?perf.memory.toFixed(2)+' MiB':'不可用'}</p><small>帧率来自当前环境，不代表真实手机性能。</small></aside>{/if}
 {#if message}<div class="toast" role="status">{message}<button aria-label="关闭提示" onclick={()=>message=''}>关闭</button></div>{/if}
</div>
